"""Instances carrying two or three flaws, generated by chaining the single-flaw path.

reviewer's brief (sync 25.08.): *"just random pick two and merge them … generate a
new flaw chart that includes these two flaws and you also need to include the
metadata so it is there for your later on evaluation."* Chaining does exactly
that and reuses the whole single-flaw machinery: the ground-truth script gets
flaw A, the result gets flaw B, and each step is the ordinary generator call with
its ordinary category instruction. Nothing about the prompts changes, so a
two-flaw instance is not a different kind of artifact, only a longer one.

Flaws interact, and a merge that destroys one of them would divide recovery by
the wrong number. Two defences, in this order:

  1. A conservative list of interaction-prone pairs, excluded from this pilot
     before any API call. Some are mutually exclusive; others are deliberately
     omitted because attribution is unreliable, not because they are impossible.
  2. A measured survival check afterwards: capture the figure objects of A alone,
     B alone and the chained AB, and demand that the combined footprint still
     covers what each flaw did on its own. A pair that passes the list but
     collapses in practice is rejected here, with the lost paths recorded.

Order matters for the second check but not for the benchmark: AB and BA are the
same instance to an agent, so the pair is drawn unordered and the chain order is
seeded, not arbitrary.

Usage:
    .venv/bin/python src/multiflaw.py --n 40 --flaws 2                  # dry run
    CRB_MODEL=claude-sonnet-5 .venv/bin/python src/multiflaw.py --n 40 --flaws 2 --allow-api
"""
import argparse
import itertools
import json
import os
import random
import tempfile
import sys
import threading
from collections import Counter
from concurrent.futures import ThreadPoolExecutor, as_completed
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import job_preconditions  # noqa: E402
import axis_inject  # noqa: E402
import llm_perturb  # noqa: E402

ROOT = Path(__file__).resolve().parent.parent
V0 = ROOT / "data/v0"
SAMPLES = V0 / "samples"
OUT_CACHE = V0 / "multiflaw.json"
SEED = 42

# What a record verified by `survives_chain` in this version claims. The
# materializer admits exactly the bases it knows, so a record from an older or
# a different check can never slip into a dataset unlabelled.
CHAIN_BASIS = "chain-stages-v13"

# Decision of 01.09. (v1.2 recipe, scaled): besides the non-empty footprint
# only the MissingLegend and the clipping AxisTruncation postconditions bind.
# The chain check evaluates exactly these per stage and on the final chart;
# the other eight figure-object gates stay diagnostic, as they do for
# single-flaw instances in dataset.py (BOUND_POSTCONDITIONS["v1.3"]).
BOUND_CHAIN_POSTCONDITIONS = frozenset({"missing-legend", "axis-truncation"})

# Conservative pilot exclusions.  The wording "may" is deliberate: not every
# pair below is mathematically impossible.  The pilot omits pairs whose effects
# its current survival check cannot attribute reliably.
EXCLUDED_PAIRS = {
    frozenset(("missing-legend", "swapped-legend-labels")):
        "swapping the labels of a legend that was removed shows nothing",
    # the two below were not predicted, they were measured: both collapsed in the
    # first pilot, and the reason each time is exact cancellation, not chance
    frozenset(("swapped-legend-labels", "swapped-series")):
        "swapping the series and then swapping their labels restores the original pairing",
    frozenset(("dropped-series", "value-perturbation")):
        "the perturbed value may sit in the series that is then dropped, hiding it",
    frozenset(("missing-legend", "color-contradicts-summary")):
        "without a legend the colour claim loses the element it was attached to",
    frozenset(("dropped-series", "swapped-legend-labels")):
        "the dropped series may be the one whose label was swapped",
    frozenset(("dropped-series", "swapped-series")):
        "both rewrite the series set; which flaw a missing series belongs to is undecidable",
    frozenset(("wrong-chart-type", "axis-truncation")):
        "a chart-type swap can remove the zero baseline the truncation needs",
    frozenset(("wrong-chart-type", "missing-legend")):
        "the new chart type may not draw a legend at all",
    frozenset(("value-perturbation", "axis-truncation")):
        "moved values move the autoscaled axis, so the truncation is no longer separable",
}


# Prepended to every call after the first. Without it the second call reads a
# script that contradicts the summary it is told to trust and quietly repairs
# the first flaw while injecting the second — measured as four of six collapses
# in the first pilot, across category pairs that have nothing structural in
# common (value-perturbation+wrong-title among them).
CHAIN_PREAMBLE = """IMPORTANT — this script is NOT the original chart. It already carries a
deliberate, intentional flaw ({previous}) that contradicts summary.txt and table.csv on purpose.
That flaw is wanted and must survive your edit byte for byte. Do NOT repair it, do NOT align the
code back to the summary or the table, and do not comment on it. Inject only the flaw described
below, on top of what is already there.

"""


# How easily a later call in the chain undoes a flaw, most fragile last. The
# order is measured, not guessed: with the preamble in place, value-perturbation
# still collapsed in 5 of 10 remaining cases across three unrelated partners,
# because the table in the prompt states the true numbers and the model writes
# them back while injecting the next flaw. Nothing can repair the last flaw,
# so the fragile ones go there.
FRAGILITY = {
    "value-perturbation": 3,
    "swapped-series": 2,
    "color-contradicts-summary": 2,
    "axis-truncation": 1,
    "dropped-series": 1,
    "swapped-legend-labels": 1,
    "missing-legend": 0,
    "wrong-axis-label": 0,
    "wrong-chart-type": 0,
    "wrong-title": 0,
}


def chain_order(categories):
    """Injection order for one instance: least repairable flaw first."""
    return tuple(sorted(categories, key=lambda c: (FRAGILITY.get(c, 0), c)))


def compatible(a, b):
    return EXCLUDED_PAIRS.get(frozenset((a, b))) is None


def pairs_for(sample, cats, rng, k):
    """k compatible category tuples this sample actually supports."""
    combos = [c for c in itertools.combinations(sorted(cats), k)
              if all(compatible(x, y) for x, y in itertools.combinations(c, 2))]
    rng.shuffle(combos)
    return combos


def applicable_categories(folder, proven=None):
    """Which categories this sample supports.

    `proven` restricts to categories that already produced a single-flaw
    instance for this very sample. The static preconditions are deliberately
    loose — they exist to decide whether a job is worth one API call, not to
    predict the generator's verdict — so chaining on them alone wasted a paid
    first flaw whenever the second was declined (measured: 12 of 30 in the
    pilot, every one of them a decline, never a collapse). Proven categories
    cannot be declined: the model already did them on this code.
    """
    d = SAMPLES / folder
    code = (d / "gt/code.py").read_text(encoding="utf-8")
    meta = json.loads((d / "meta.json").read_text())
    summary = (d / "gt/summary.txt").read_text(encoding="utf-8")
    csv_text = (d / "gt/table.csv").read_text(encoding="utf-8")
    if proven is not None:
        return set(proven.get(folder, ())), code, meta, summary, csv_text
    cats = {c for c in job_preconditions.CATEGORIES
            if job_preconditions.applies(c, code, meta, summary, csv_text)}
    return cats, code, meta, summary, csv_text


def proven_categories():
    """{folder: {categories that already have a rendered single-flaw instance}}.

    Materialized multi-flaw instances live under the same tree in folders named
    `multi2`, `multi3`, … Those are not flaw categories and must never enter a
    combination: chaining "axis-truncation + multi2" would stack a pair on top
    of a pair and lose track of what the instance contains.
    """
    out = {}
    for code in SAMPLES.glob("*/perturbed_llm/*/code.py"):
        category = code.parent.name
        if category in job_preconditions.CATEGORIES:
            out.setdefault(code.parents[2].name, set()).add(category)
    return out


def _capture_inline(d, code, extra, timeout, capture_path, prefix):
    """Capture generated code through a per-call file in its sample directory.

    A fixed probe name is unsafe here: the generator verifies several category
    combinations concurrently, often on the same source chart.  One worker can
    otherwise overwrite or unlink another worker's script before capture.
    """
    fd, raw_path = tempfile.mkstemp(dir=d, prefix=prefix, suffix=".py", text=True)
    path = Path(raw_path)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as stream:
            stream.write(code)
        return capture_path(path, extra, timeout)
    finally:
        path.unlink(missing_ok=True)


def survives_chain(folder, categories, stages, timeout=120):
    """Verify from the chain's own intermediate scripts, not from files on disk.

    Every step of the chain produces the script that carries exactly the flaws
    injected so far, so step k's contribution is footprint(stage k-1, stage k) —
    no single-flaw instance has to exist anywhere. This is both stricter and
    freer than comparing against `perturbed_llm/<category>/code.py`: stricter
    because it isolates each flaw's own paths rather than a differently
    generated instance of the same category, and freer because it works on any
    source chart. Comparing against disk was what made the broader candidate
    pool useless — 46 of 49 instances came back 'unverified' simply because no
    solo instance happened to exist for that sample.

    `stages` is [code after flaw 1, after flaw 2, …]; the last one is the
    instance itself.
    """
    from eval.capture import capture_path
    from eval.metrics import footprint
    from eval.semantic_gates import category_postcondition

    d = SAMPLES / folder
    extra = {"table.csv": (d / "gt/table.csv").read_text(encoding="utf-8", errors="replace")}
    sp = d / "gt/summary.txt"
    if sp.exists():
        extra["summary.txt"] = sp.read_text(encoding="utf-8", errors="replace")

    caps = []
    gt = capture_path(d / "gt/code.py", extra, timeout)
    if gt["status"] != "ok":
        return "unverified", {"reason": "gt capture failed"}
    for code in stages:
        caps.append(_capture_inline(
            d, code, extra, timeout, capture_path, "_chain_probe_"))

    if caps[-1]["status"] != "ok":
        return "collapsed", {"reason": "combined script does not render"}
    combined = set(footprint(gt["flat"], caps[-1]["flat"], "strict"))
    detail, lost, unproven = {}, [], []
    prev = gt
    for cat, cap in zip(categories, caps):
        if cap["status"] != "ok":
            detail[cat] = "intermediate script does not render"
            unproven.append(cat)
            prev = cap
            continue
        own = set(footprint(prev["flat"], cap["flat"], "strict"))
        kept = own & combined
        detail[cat] = {"own_paths": len(own), "kept_in_combined": len(kept)}
        semantic = (category_postcondition(cat, prev["flat"], cap["flat"])
                    if cat in BOUND_CHAIN_POSTCONDITIONS else None)
        if semantic is not None:
            detail[cat]["semantic_gate"] = semantic
            # Diagnostic only. The V2 gates also reject collateral change, and
            # the final chart necessarily carries the OTHER flaws: measured on
            # 02.09., every one of the first nine "collapsed" pairs had its stage
            # gate green and all its paths kept, and failed the final chart with
            # series_encoding_changed / data_changed_or_deleted /
            # collateral_semantic_change, i.e. with its partner's edit. What
            # binds is the stage gate plus the survival of the stage's own paths
            # into the final chart (the V2 multiflow-final contract reached the
            # same conclusion).
            detail[cat]["semantic_gate_final"] = category_postcondition(
                cat, prev["flat"], caps[-1]["flat"])
        if semantic is not None and not semantic["ok"]:
            unproven.append(cat)
        elif own and not kept:
            lost.append(cat)
        elif not own:
            unproven.append(cat)          # this step changed nothing at all
        prev = cap
    verdict = "collapsed" if lost else ("unverified" if unproven else "verified")
    return verdict, {"combined_paths": sorted(combined)[:12], "per_flaw": detail,
                     "lost": lost, "unproven": unproven,
                     "verification_basis": CHAIN_BASIS,
                     "bound_postconditions": sorted(BOUND_CHAIN_POSTCONDITIONS)}


_last_write = [0.0]
WRITE_EVERY_SECONDS = 30.0


def _write_cache(cache: dict, force: bool = False) -> None:
    """Write the cache atomically, at most every 30 s unless forced.

    A crash mid-write must not eat a day's chains, hence the temp file and
    rename. But dumping the whole file after every job became the bottleneck
    once it held 12k records (~80 MB): at ten chains a minute the main thread
    spent most of its time serialising JSON (90 % CPU, 03.09.). Thirty seconds
    between writes bounds the loss on a crash to a handful of chains.
    """
    import time
    now = time.time()
    if not force and now - _last_write[0] < WRITE_EVERY_SECONDS:
        return
    tmp = OUT_CACHE.with_suffix(".json.tmp")
    tmp.write_text(json.dumps(cache, indent=1))
    os.replace(tmp, OUT_CACHE)
    _last_write[0] = now


def survives(folder, categories, combined_code, timeout=120):
    """Does the chained script still show what each flaw did on its own?

    Compares three footprints against the ground truth: one per flaw alone and
    one for the chain. A flaw whose paths vanished from the combined footprint
    was overwritten by its partner, and the instance would ask an agent to repair
    something that is not there.

    Returns one of three verdicts, never a bare boolean: "verified" (every flaw
    had a single-flaw instance to compare against and kept paths in the chain),
    "collapsed" (a flaw's paths are gone), "unverified" (at least one flaw had no
    comparison basis, so nothing was proven). Counting "unverified" as success is
    the vacuous-truth trap this project has already paid for once in
    gates.check_solvable — an unprovable claim is not a true one.
    """
    from eval.capture import capture_path
    from eval.metrics import footprint
    from eval.semantic_gates import category_postcondition

    d = SAMPLES / folder
    extra = {"table.csv": (d / "gt/table.csv").read_text(encoding="utf-8", errors="replace")}
    sp = d / "gt/summary.txt"
    if sp.exists():
        extra["summary.txt"] = sp.read_text(encoding="utf-8", errors="replace")
    gt = capture_path(d / "gt/code.py", extra, timeout)
    if gt["status"] != "ok":
        return "unverified", {"reason": "gt capture failed"}

    comb = _capture_inline(
        d, combined_code, extra, timeout, capture_path, "_multiflaw_probe_")
    if comb["status"] != "ok":
        return "collapsed", {"reason": "combined script does not render"}

    combined_fp = set(footprint(gt["flat"], comb["flat"], "strict"))
    detail, lost, unproven = {}, [], []
    for cat in categories:
        solo = SAMPLES / folder / "perturbed_llm" / cat / "code.py"
        if not solo.exists():
            detail[cat] = "no single-flaw instance to compare against"
            unproven.append(cat)
            continue
        cap = capture_path(solo, extra, timeout)
        if cap["status"] != "ok":
            detail[cat] = "single-flaw script does not render"
            unproven.append(cat)
            continue
        solo_fp = set(footprint(gt["flat"], cap["flat"], "strict"))
        kept = solo_fp & combined_fp
        detail[cat] = {"solo_paths": len(solo_fp), "kept_in_combined": len(kept)}
        semantic = category_postcondition(cat, gt["flat"], cap["flat"])
        if semantic is not None:
            final_semantic = category_postcondition(cat, gt["flat"], comb["flat"])
            detail[cat]["semantic_gate"] = semantic
            detail[cat]["semantic_gate_final"] = final_semantic
        if semantic is not None and not semantic["ok"]:
            unproven.append(cat)
        elif semantic is not None and not final_semantic["ok"]:
            lost.append(cat)
        elif solo_fp and not kept:
            lost.append(cat)
        elif not solo_fp:
            unproven.append(cat)          # the single flaw was itself a no-op
    verdict = "collapsed" if lost else ("unverified" if unproven else "verified")
    return verdict, {"combined_paths": sorted(combined_fp)[:12], "per_flaw": detail,
                     "lost": lost, "unproven": unproven}


def semantic_survival(folder, categories, combined_code, timeout=120):
    """Recheck only category postconditions from GT to the final chart.

    Unlike :func:`survives`, this deliberately does not require cached
    single-flaw scripts. It is the safe migration path for chain-verified
    records whose intermediate stages were not materialized on disk: re-running
    the legacy comparison would turn them into ``unverified`` for lack of a solo
    file even though the chain originally proved every step.
    """
    from eval.capture import capture_path
    from eval.semantic_gates import category_postcondition

    d = SAMPLES / folder
    extra = {"table.csv": (d / "gt/table.csv").read_text(encoding="utf-8", errors="replace")}
    sp = d / "gt/summary.txt"
    if sp.exists():
        extra["summary.txt"] = sp.read_text(encoding="utf-8", errors="replace")
    gt = capture_path(d / "gt/code.py", extra, timeout)
    if gt["status"] != "ok":
        return "unverified", {"status": "gt_capture_failed", "gt_status": gt["status"]}

    combined = _capture_inline(
        d, combined_code, extra, timeout, capture_path, "_semantic_probe_")
    if combined["status"] != "ok":
        return "collapsed", {"status": "combined_capture_failed",
                             "combined_status": combined["status"]}

    gates = {}
    for category in categories:
        gate = category_postcondition(category, gt["flat"], combined["flat"])
        if gate is not None:
            gates[category] = gate
    if not gates:
        return "unverified", {"status": "no_semantic_gate", "gates": {}}
    ok = all(gate["ok"] is True for gate in gates.values())
    return ("verified" if ok else "collapsed"), {
        "status": "ok" if ok else "semantic_gate_failed",
        "gates": gates,
    }


def load_cache():
    return json.loads(OUT_CACHE.read_text()) if OUT_CACHE.exists() else {}


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--n", type=int, default=40, help="instances to build")
    ap.add_argument("--per-combination", type=int, default=None, metavar="N",
                    help="fill EVERY admissible combination to N instances instead of "
                         "drawing whatever a sample happens to support. Without this the "
                         "coverage is badly skewed: measured 38 instances on one pair "
                         "and none at all on two others")
    ap.add_argument("--budget-usd", type=float, default=None,
                    help="stop before the estimated spend crosses this")
    ap.add_argument("--workers", type=int, default=6,
                    help="instances chained in parallel; each one is a few API "
                         "calls plus three local script runs")
    ap.add_argument("--flaws", type=int, default=2, choices=(2, 3, 4))
    ap.add_argument("--allow-api", action="store_true", help="actually spend money")
    ap.add_argument("--matrix", action="store_true",
                    help="print which category pairs are possible at all, then exit")
    ap.add_argument("--provider", choices=("endpoint", "anthropic"), default="endpoint",
                    help="endpoint (default since 01.09.) or anthropic (historical path)")
    ap.add_argument("--model", default=None, help="ENDPOINT slug or Anthropic model id")
    ap.add_argument("--endpoint-concurrency", type=int, default=8)
    ap.add_argument("--loose", action="store_true",
                    help="draw pairs from the static preconditions instead of from "
                         "categories already proven on this sample (wastes paid first "
                         "flaws when the second is declined)")
    args = ap.parse_args()

    cats = sorted(job_preconditions.CATEGORIES)
    if args.matrix:
        print(f"{len(cats)} categories · "
              f"{len(list(itertools.combinations(cats, 2)))} unordered pairs · "
              f"{len(EXCLUDED_PAIRS)} conservatively excluded from this pilot\n")
        for a, b in itertools.combinations(cats, 2):
            why = EXCLUDED_PAIRS.get(frozenset((a, b)))
            if why:
                print(f"  excluded  {a} + {b}\n            {why}")
        ok = [c for c in itertools.combinations(cats, 2) if compatible(*c)]
        print(f"\n{len(ok)} pairs remain for generation")
        return

    index = json.loads((V0 / "index.json").read_text())
    rng = random.Random(SEED)
    pool = [e["folder"] for e in index
            if (SAMPLES / e["folder"] / "gt/exec.json").exists()
            and json.loads((SAMPLES / e["folder"] / "gt/exec.json").read_text()).get("status") == "ok"]
    rng.shuffle(pool)
    proven = None if args.loose else proven_categories()

    cache = load_cache()

    def load(folder):
        d = SAMPLES / folder
        return {"folder": folder,
                "meta": json.loads((d / "meta.json").read_text()),
                "code": (d / "gt/code.py").read_text(encoding="utf-8"),
                "summary": (d / "gt/summary.txt").read_text(encoding="utf-8"),
                "csv": (d / "gt/table.csv").read_text(encoding="utf-8")}

    jobs = []
    if args.per_combination:
        # Category sets per sample once, then fill each combination from the
        # samples that support all of its members.
        support = {}
        for folder in pool:
            try:
                cats_here, *_ = applicable_categories(folder, proven)
            except (OSError, SyntaxError):
                continue
            support[folder] = cats_here
        combos = [c for c in itertools.combinations(sorted(job_preconditions.CATEGORIES),
                                                    args.flaws)
                  if all(compatible(x, y) for x, y in itertools.combinations(c, 2))]
        have = Counter()
        for rec in cache.values():
            if len(rec.get("categories", ())) == args.flaws and rec.get("verdict") == "verified":
                have[tuple(sorted(rec["categories"]))] += 1
        queues = []
        for combo in combos:
            need = args.per_combination - have[tuple(sorted(combo))]
            if need <= 0:
                continue
            cands = [f for f, s in support.items()
                     if all(c in s for c in combo)
                     and f"{f}|{'+'.join(combo)}" not in cache]
            rng.shuffle(cands)
            queues.append((combo, cands[:need]))
        # Round robin over the combinations rather than one combination after
        # another: a budget cap, an interruption or a crash then costs every
        # combination the same tail instead of wiping the last ones entirely.
        for i in range(max((len(q) for _, q in queues), default=0)):
            for combo, q in queues:
                if i < len(q):
                    try:
                        jobs.append({**load(q[i]), "categories": combo})
                    except OSError:
                        continue
    else:
        for folder in pool:
            if len(jobs) >= args.n:
                break
            try:
                avail, code, meta, summary, csv_text = applicable_categories(folder, proven)
            except (OSError, SyntaxError):
                continue
            combos = pairs_for(folder, avail, rng, args.flaws)
            if not combos:
                continue
            combo = combos[0]
            if f"{folder}|{'+'.join(combo)}" in cache:
                continue
            jobs.append({"folder": folder, "categories": combo, "meta": meta,
                         "code": code, "summary": summary, "csv": csv_text})

    if args.budget_usd:
        # Two to four generator calls per instance; the estimate is the measured
        # ~$0.0105 per flaw injected, so a run cannot quietly outspend its cap.
        per = 0.0105 * args.flaws
        keep = int(args.budget_usd / per)
        if keep < len(jobs):
            print(f"budget ${args.budget_usd:.2f} allows about {keep} of {len(jobs)} jobs")
            jobs = jobs[:keep]

    print(f"{len(jobs)} multi-flaw jobs ({args.flaws} flaws each), "
          f"{len(cache)} already cached")
    print("category pairs:", dict(Counter("+".join(j["categories"]) for j in jobs).most_common(6)))
    if not args.allow_api:
        chars = sum(len(j["code"]) for j in jobs) * args.flaws
        print(f"\nDRY RUN — no API call. ~{chars // 4000}k input tokens, "
              f"roughly ${chars / 4000 * args.flaws * 0.004:.2f} with sonnet.")
        print("Run with --allow-api to generate.")
        return

    if args.provider == "endpoint":
        client = llm_perturb.ENDPOINTClient(args.model or llm_perturb.ENDPOINT_MODEL,
                                        concurrency_per_key=args.endpoint_concurrency)
        generator_model = client.model
        print(f"generator: ENDPOINT {client.slug} (served as {generator_model})")
    else:
        if not os.environ.get("ANTHROPIC_API_KEY"):
            sys.exit("ANTHROPIC_API_KEY not set")
        import anthropic
        # An explicit per-request deadline: the default client waits ten minutes and
        # retries twice, so one hung request can occupy a worker for half an hour.
        # A generation that has not answered in three minutes is not coming.
        client = anthropic.Anthropic(timeout=180.0, max_retries=2)
        generator_model = llm_perturb.MODEL

    built, refused = 0, Counter()
    lock = threading.Lock()

    def one(job):
        """Chain the flaws for a single instance, then prove they survived."""
        code = job["code"]
        chain, stages = [], []
        for step, cat in enumerate(chain_order(job["categories"])):
            single = {"sample_id": job["meta"]["id"], "category": cat,
                      "library": job["meta"]["library"],
                      "chart_type": job["meta"]["chart_type"]}
            if cat == "axis-truncation":
                # Decision of 28.08./01.09.: the axis flaw is the deterministic
                # data clip, never an LLM edit, also inside a chain.
                rec, status = axis_inject.inject_code(
                    code, {"table.csv": job["csv"], "summary.txt": job["summary"]},
                    job["meta"]["library"])
            else:
                rec, status = llm_perturb.generate_one(
                    client, single, code, job["summary"], job["csv"],
                    preamble=CHAIN_PREAMBLE.format(
                        previous=", ".join(e["category"] for e in chain)) if step else "",
                    previous_flaws=tuple(e["category"] for e in chain))
            if not rec or not rec.get("perturbed_code"):
                return job, None, f"{cat}:{status[:24]}", None
            chain.append({"category": cat, "description": rec["description"],
                          "evidence": rec.get("evidence", {}),
                          **({"target": rec["target"]} if rec.get("target") else {})})
            code = rec["perturbed_code"]
            stages.append(code)
        verdict, detail = survives_chain(
            job["folder"], chain_order(job["categories"]), stages)
        return job, chain, verdict, (code, detail, stages)

    # Threads, not a sequential loop: a job is two or three API calls plus three
    # script executions, so the wall clock was ~38 s each and a full build ran
    # for the better part of a day. The cache is written under a lock after
    # every job, so an interrupted run keeps everything it paid for.
    # as_completed, not map: map yields in submission order, so a single slow
    # job blocks every finished one behind it. Measured the hard way — the sweep
    # sat at 0 % CPU for two hours with nine idle workers waiting on one call.
    with ThreadPoolExecutor(max_workers=args.workers) as ex:
        futures = [ex.submit(one, j) for j in jobs]
        for fut in as_completed(futures):
            try:
                job, chain, verdict, extra = fut.result()
            except Exception as exc:            # noqa: BLE001 - one job, not the run
                with lock:
                    refused["job_error_%s" % type(exc).__name__[:20]] += 1
                continue
            if chain is None:
                with lock:
                    refused[verdict] += 1
                continue
            code, detail, stages = extra
            key = f"{job['folder']}|{'+'.join(job['categories'])}"
            with lock:
                cache[key] = {"folder": job["folder"], "categories": list(job["categories"]),
                              "edits": chain, "perturbed_code": code,
                              "stages": stages,
                              "verdict": verdict, "survival_detail": detail,
                              "model": generator_model,
                              "v1_policy": f"{args.flaws} flaws per instance"}
                _write_cache(cache)
                built += verdict == "verified"
                if verdict != "verified":
                    refused[f"{verdict}:{','.join(detail.get('lost') or detail.get('unproven') or []) or detail.get('reason', '?')}"] += 1
                print(f"  {key}: {verdict}", flush=True)

    _write_cache(cache, force=True)
    print(f"\n{built} instances with every flaw proven to survive · "
          f"{len(jobs) - built} not usable: {dict(refused)}")
    print(f"-> {OUT_CACHE}")


if __name__ == "__main__":
    main()
